16: // R-01/R-06: absence retains its established sentinel for both read modes.
17: func TestChatReadMissingHeaderIsNotFound(t *testing.T) {
18: 	s, cleanup := setupTestStore(t)
19: 	t.Cleanup(cleanup)
20: 	for _, attachments := range []bool{false, true} {
21: 		chat, err := s.ChatWithOptions("absent-chat", attachments)
22: 		if chat != nil || !errors.Is(err, not.Found) {
23: 			t.Errorf("attachments=%t: chat=%#v error=%v; want absence", attachments, chat, err)
24: 		}
25: 	}
26: }
