28: // R-01/R-05: missing child rows are empty collections, not missing chats.
29: func TestChatReadValidEmptyAndPopulated(t *testing.T) {
30: 	s, cleanup := setupTestStore(t)
31: 	t.Cleanup(cleanup)
32: 	for _, populated := range []bool{false, true} {
33: 		want := NewChat("valid-chat")
34: 		want.Title = "retained title"
35: 		if populated {
36: 			want.Messages = []Message{
37: 				NewMessage("user", "first original body", nil),
38: 				NewMessage("assistant", "second original body", nil),
39: 			}
40: 		}
41: 		if err := s.SetChat(*want); err != nil {
42: 			t.Fatal(err)
43: 		}
44: 		for _, attachments := range []bool{false, true} {
45: 			got, err := s.ChatWithOptions(want.ID, attachments)
46: 			if err != nil || got == nil {
47: 				t.Fatalf("populated=%t attachments=%t: valid read failed: %v", populated, attachments, err)
48: 			}
49: 			if got.ID != want.ID || got.Title != want.Title || len(got.Messages) != len(want.Messages) {
50: 				t.Fatalf("R-05: valid chat changed: got=%#v want=%#v", got, want)
51: 			}
52: 			for i, msg := range want.Messages {
53: 				if got.Messages[i].Content != msg.Content || got.Messages[i].Role != msg.Role {
54: 					t.Errorf("R-05: message %d changed: %#v", i, got.Messages[i])
55: 				}
56: 			}
57: 		}
58: 	}
59: }
