99: // R-02: failure before the query must not authorise creation either.
100: func TestChatReadInitialisationFailureIsNotAbsence(t *testing.T) {
101: 	blocker := filepath.Join(t.TempDir(), "regular-file")
102: 	if err := os.WriteFile(blocker, []byte("not a directory"), 0o600); err != nil {
103: 		t.Fatal(err)
104: 	}
105: 	s := &Store{DBPath: filepath.Join(blocker, "db.sqlite")}
106: 	t.Cleanup(func() { s.Close() })
107: 	for _, attachments := range []bool{false, true} {
108: 		chat, err := s.ChatWithOptions("any-chat", attachments)
109: 		var cause *os.PathError
110: 		if chat != nil || err == nil || errors.Is(err, not.Found) || !errors.As(err, &cause) {
111: 			t.Errorf("R-02: initialisation failure lost its path cause: chat=%#v err=%v", chat, err)
112: 		}
113: 	}
114: }
