116: // R-02: a native database failure keeps the original error identity, rather
117: // than merely acquiring a different error message containing the same words.
118: func TestChatReadPreservesDatabaseErrorCause(t *testing.T) {
119: 	s, cleanup := setupTestStore(t)
120: 	t.Cleanup(cleanup)
121: 	if err := s.SetChat(*NewChat("existing-chat")); err != nil {
122: 		t.Fatal(err)
123: 	}
124: 	if err := s.Close(); err != nil {
125: 		t.Fatal(err)
126: 	}
127: 	cause := s.db.conn.Ping()
128: 	if cause == nil {
129: 		t.Fatal("closing the real database did not produce a database error")
130: 	}
131: 	for _, attachments := range []bool{false, true} {
132: 		chat, err := s.ChatWithOptions("existing-chat", attachments)
133: 		if chat != nil || err == nil {
134: 			t.Fatalf("attachments=%t: closed database returned chat=%#v error=%v", attachments, chat, err)
135: 		}
136: 		if errors.Is(err, not.Found) {
137: 			t.Errorf("R-02: database failure became absence: %v", err)
138: 		}
139: 		if !errors.Is(err, cause) {
140: 			t.Errorf("R-02: database error identity lost: got=%v cause=%v", err, cause)
141: 		}
142: 	}
143: }
